static double now_s(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return(double)ts.tv_sec+(double)ts.tv_nsec*1e-9;}
static int cmp_double(const void*a,const void*b){double x=*(const double*)a,y=*(const double*)b;return(x>y)-(x<y);}
static double median(double*v,int n){qsort(v,(size_t)n,sizeof(*v),cmp_double);return(n&1)?v[n/2]:.5*(v[n/2-1]+v[n/2]);}
static void emit(const char*k,uint64_t u,int r,double s,double rate,uint64_t c){printf("RESULT kernel=%s units=%" PRIu64 " rounds=%d seconds=%.9f rate=%.6f checksum=%" PRIu64 "\n",k,u,r,s,rate,c);}
static uint64_t mix64(uint64_t x){x+=UINT64_C(0x9e3779b97f4a7c15);x=(x^(x>>30))*UINT64_C(0xbf58476d1ce4e5b9);x=(x^(x>>27))*UINT64_C(0x94d049bb133111eb);return x^(x>>31);}
static uint64_t c32(const uint32_t*a,size_t n){uint64_t h=UINT64_C(1469598103934665603);for(size_t i=0;i<n;i++){h^=(uint64_t)a[i]+(uint64_t)i*UINT64_C(0x9e3779b1);h*=UINT64_C(1099511628211);}return h;}
static uint64_t c64(const uint64_t*a,size_t n){uint64_t h=UINT64_C(1469598103934665603);for(size_t i=0;i<n;i++){h^=a[i]+(uint64_t)i*UINT64_C(0x9e3779b97f4a7c15);h*=UINT64_C(1099511628211);}return h;}

static uint64_t integer50(uint64_t n){const uint64_t mask=(UINT64_C(1)<<50)-1;uint64_t x=UINT64_C(88172645463325252)&mask,sum=0;for(uint64_t i=0;i<n;i++){x^=x>>7;x^=(x<<8)&mask;x^=x>>9;x&=mask;sum=(sum+(x^(x>>17)))&mask;}return sum;}
static int bench_integer(uint64_t n,int r){(void)integer50(n/20+1);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=0;for(int i=0;i<r;i++){double a=now_s();c=integer50(n);t[i]=now_s()-a;}double m=median(t,r);emit("integer50",n,r,m,(double)n/m/1e6,c);free(t);return 0;}

static const uint8_t PAT[]={'a','l','p','h','a','"','b','e','t','a','\\','g','a','m','m','a','\n','\t',1,'x','y','z','/'};
static size_t json_escape(const uint8_t*in,size_t n,uint8_t*out){static const char hex[]="0123456789abcdef";size_t j=0;out[j++]='"';for(size_t i=0;i<n;i++){uint8_t c=in[i];switch(c){case '"':out[j++]='\\';out[j++]='"';break;case '\\':out[j++]='\\';out[j++]='\\';break;case '\b':out[j++]='\\';out[j++]='b';break;case '\f':out[j++]='\\';out[j++]='f';break;case '\n':out[j++]='\\';out[j++]='n';break;case '\r':out[j++]='\\';out[j++]='r';break;case '\t':out[j++]='\\';out[j++]='t';break;default:if(c<32){out[j++]='\\';out[j++]='u';out[j++]='0';out[j++]='0';out[j++]=(uint8_t)hex[c>>4];out[j++]=(uint8_t)hex[c&15];}else out[j++]=c;}}out[j++]='"';return j;}
static int bench_json(uint64_t n,int r){uint8_t*in=malloc((size_t)n),*out=malloc((size_t)n*6+2);double*t=malloc((size_t)r*sizeof(*t));for(size_t i=0;i<(size_t)n;i++)in[i]=PAT[i%23];size_t on=json_escape(in,n,out);for(int i=0;i<r;i++){double a=now_s();on=json_escape(in,n,out);t[i]=now_s()-a;}uint64_t c=on;for(size_t i=0;i<on;i++)c+=out[i];double m=median(t,r);emit("json_escape",n,r,m,(double)n/m/1e9,c);free(t);free(out);free(in);return 0;}

static void merge_sort(uint32_t*a,uint32_t*tmp,size_t n){uint32_t*src=a,*dst=tmp;for(size_t w=1;w<n;w*=2){for(size_t lo=0;lo<n;lo+=2*w){size_t mid=lo+w<n?lo+w:n,hi=lo+2*w<n?lo+2*w:n,i=lo,j=mid,k=lo;while(i<mid&&j<hi)dst[k++]=src[i]<=src[j]?src[i++]:src[j++];while(i<mid)dst[k++]=src[i++];while(j<hi)dst[k++]=src[j++];}uint32_t*x=src;src=dst;dst=x;if(w>n/2)break;}if(src!=a)memcpy(a,src,n*4);}
static int bench_merge(uint64_t nu,int r){size_t n=(size_t)nu;uint32_t*base=malloc(n*4),*work=malloc(n*4),*tmp=malloc(n*4);double*t=malloc((size_t)r*sizeof(*t));for(size_t i=0;i<n;i++)base[i]=(uint32_t)mix64(i);memcpy(work,base,n*4);merge_sort(work,tmp,n);for(int x=0;x<r;x++){memcpy(work,base,n*4);double a=now_s();merge_sort(work,tmp,n);t[x]=now_s()-a;}uint64_t c=c32(work,n);double m=median(t,r);emit("merge_sort",nu,r,m,(double)n/m/1e6,c);free(t);free(tmp);free(work);free(base);return 0;}

static int64_t bs(const uint32_t*a,size_t n,uint32_t x){size_t lo=0,hi=n;while(lo<hi){size_t m=lo+(hi-lo)/2;if(a[m]<x)lo=m+1;else hi=m;}return lo<n&&a[lo]==x?(int64_t)lo:-1;}
static uint64_t bs_once(const uint32_t*a,size_t n,uint64_t q){uint64_t h=0;for(uint64_t i=0;i<q;i++){int64_t p=bs(a,n,(uint32_t)(mix64(i)%(2*n)));h+=p>=0?(uint64_t)p+1:0;}return h;}
static int bench_bs(uint64_t nu,int r){size_t n=(size_t)nu;uint64_t q=nu*4;uint32_t*a=malloc(n*4);double*t=malloc((size_t)r*sizeof(*t));for(size_t i=0;i<n;i++)a[i]=(uint32_t)(i*2);uint64_t c=bs_once(a,n,q/20+1);for(int x=0;x<r;x++){double s=now_s();c=bs_once(a,n,q);t[x]=now_s()-s;}double m=median(t,r);emit("binary_search",q,r,m,(double)q/m/1e6,c);free(t);free(a);return 0;}

static uint64_t prefix_once(const uint32_t*in,uint64_t*out,size_t n,int passes){uint64_t c=0;for(int p=0;p<passes;p++){uint64_t s=(uint64_t)p;for(size_t i=0;i<n;i++){s+=in[i];out[i]=s;}c^=s;}return c;}
static int bench_prefix(uint64_t nu,int r){const int passes=16;size_t n=(size_t)nu;uint32_t*in=malloc(n*4);uint64_t*out=malloc(n*8);double*t=malloc((size_t)r*sizeof(*t));for(size_t i=0;i<n;i++)in[i]=(uint32_t)(mix64(i)&1023);uint64_t c=prefix_once(in,out,n,1);for(int x=0;x<r;x++){double s=now_s();c=prefix_once(in,out,n,passes);t[x]=now_s()-s;}c^=c64(out,n);double m=median(t,r);emit("prefix_sum",nu*passes,r,m,(double)n*passes/m/1e6,c);free(t);free(out);free(in);return 0;}

static void mm(const uint32_t*a,const uint32_t*b,uint64_t*c,size_t n){for(size_t i=0;i<n;i++)for(size_t j=0;j<n;j++){uint64_t s=0;for(size_t k=0;k<n;k++)s+=(uint64_t)a[i*n+k]*b[k*n+j];c[i*n+j]=s;}}
static int bench_mm(uint64_t nu,int r){size_t n=(size_t)nu,nn=n*n;uint32_t*a=malloc(nn*4),*b=malloc(nn*4);uint64_t*c=malloc(nn*8);double*t=malloc((size_t)r*sizeof(*t));for(size_t i=0;i<nn;i++){a[i]=(uint32_t)(mix64(i)&15);b[i]=(uint32_t)(mix64(i+nn)&15);}mm(a,b,c,n);for(int x=0;x<r;x++){double s=now_s();mm(a,b,c,n);t[x]=now_s()-s;}uint64_t h=c64(c,nn);double m=median(t,r);emit("matrix_mul",nu,r,m,(double)n*n*n/m/1e6,h);free(t);free(c);free(b);free(a);return 0;}

static void graph(uint32_t*adj,uint32_t*w,size_t n,int d){for(size_t i=0;i<n;i++)for(int e=0;e<d;e++){size_t p=i*(size_t)d+e;uint32_t v=e==0?(uint32_t)((i+1)%n):e==1?(uint32_t)((i+n-1)%n):(uint32_t)(mix64((uint64_t)i*d+e)%n);adj[p]=v;if(w)w[p]=(uint32_t)(1+(mix64(UINT64_C(0xabc00000)+p)&15));}}
static uint64_t bfs_once(const uint32_t*adj,size_t n,int d,int32_t*dist,uint32_t*q){for(size_t i=0;i<n;i++)dist[i]=-1;size_t h=0,t=0;dist[0]=0;q[t++]=0;while(h<t){uint32_t u=q[h++];int32_t nd=dist[u]+1;for(int e=0;e<d;e++){uint32_t v=adj[(size_t)u*d+e];if(dist[v]<0){dist[v]=nd;q[t++]=v;}}}uint64_t c=0;for(size_t i=0;i<n;i++)c+=(uint64_t)(dist[i]+1)*(i+1);return c;}
static uint64_t bfs_many(const uint32_t*a,size_t n,int d,int32_t*dist,uint32_t*q,int p){uint64_t h=0;for(int x=0;x<p;x++)h+=bfs_once(a,n,d,dist,q)^((uint64_t)x*UINT64_C(0x9e3779b97f4a7c15));return h;}
static int bench_bfs(uint64_t nu,int r){const int d=4,p=16;size_t n=(size_t)nu;uint32_t*a=malloc(n*d*4),*q=malloc(n*4);int32_t*dist=malloc(n*4);double*t=malloc((size_t)r*sizeof(*t));graph(a,NULL,n,d);uint64_t c=bfs_many(a,n,d,dist,q,1);for(int x=0;x<r;x++){double s=now_s();c=bfs_many(a,n,d,dist,q,p);t[x]=now_s()-s;}double m=median(t,r);emit("bfs",nu*p,r,m,(double)n*d*p/m/1e6,c);free(t);free(dist);free(q);free(a);return 0;}

struct HP{uint64_t d;uint32_t v;};
static void hppush(struct HP*h,size_t*sz,struct HP x){size_t i=(*sz)++;while(i){size_t p=(i-1)/2;if(h[p].d<=x.d)break;h[i]=h[p];i=p;}h[i]=x;}
static struct HP hppop(struct HP*h,size_t*sz){struct HP o=h[0],x=h[--*sz];size_t i=0;while(1){size_t l=i*2+1;if(l>=*sz)break;size_t r=l+1,c=r<*sz&&h[r].d<h[l].d?r:l;if(h[c].d>=x.d)break;h[i]=h[c];i=c;}if(*sz)h[i]=x;return o;}
static uint64_t dij_once(const uint32_t*a,const uint32_t*w,size_t n,int d,uint64_t*dist,struct HP*h){const uint64_t INF=UINT64_MAX/4;for(size_t i=0;i<n;i++)dist[i]=INF;size_t sz=0;dist[0]=0;hppush(h,&sz,(struct HP){0,0});while(sz){struct HP x=hppop(h,&sz);if(x.d!=dist[x.v])continue;for(int e=0;e<d;e++){size_t p=(size_t)x.v*d+e;uint32_t v=a[p];uint64_t nd=x.d+w[p];if(nd<dist[v]){dist[v]=nd;hppush(h,&sz,(struct HP){nd,v});}}}uint64_t c=0;for(size_t i=0;i<n;i++)c^=dist[i]+i*UINT64_C(0x9e3779b97f4a7c15);return c;}
static int bench_dij(uint64_t nu,int r){const int d=4;size_t n=(size_t)nu;uint32_t*a=malloc(n*d*4),*w=malloc(n*d*4);uint64_t*dist=malloc(n*8);struct HP*h=malloc(n*d*4*sizeof(*h));double*t=malloc((size_t)r*sizeof(*t));graph(a,w,n,d);uint64_t c=dij_once(a,w,n,d,dist,h);for(int x=0;x<r;x++){double s=now_s();c=dij_once(a,w,n,d,dist,h);t[x]=now_s()-s;}double m=median(t,r);emit("dijkstra",nu,r,m,(double)n*d/m/1e6,c);free(t);free(h);free(dist);free(w);free(a);return 0;}

static uint32_t uffind(uint32_t*p,uint32_t x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}
static uint64_t uf_once(uint32_t*p,uint8_t*r,size_t n,uint64_t ops){for(size_t i=0;i<n;i++){p[i]=(uint32_t)i;r[i]=0;}for(uint64_t i=0;i<ops;i++){uint32_t a=(uint32_t)(mix64(i)%n),b=(uint32_t)(mix64(i+ops)%n),ra=uffind(p,a),rb=uffind(p,b);if(ra!=rb){if(r[ra]<r[rb]){uint32_t z=ra;ra=rb;rb=z;}p[rb]=ra;if(r[ra]==r[rb])r[ra]++;}}uint64_t h=0;for(size_t i=0;i<n;i+=17)h+=uffind(p,(uint32_t)i);return h;}
static int bench_uf(uint64_t nu,int rr){size_t n=(size_t)nu;uint64_t ops=nu*4;uint32_t*p=malloc(n*4);uint8_t*r=malloc(n);double*t=malloc((size_t)rr*sizeof(*t));uint64_t c=uf_once(p,r,n,ops/20+1);for(int x=0;x<rr;x++){double s=now_s();c=uf_once(p,r,n,ops);t[x]=now_s()-s;}double m=median(t,rr);emit("union_find",ops,rr,m,(double)ops/m/1e6,c);free(t);free(r);free(p);return 0;}

static uint64_t mandel(int w,int mi){uint64_t sum=0;for(int y=0;y<w;y++){double ci=-1.5+3.0*y/(w-1.0);for(int x=0;x<w;x++){double cr=-2.0+3.0*x/(w-1.0),zr=0,zi=0;int it=0;while(it<mi){double a=zr*zr,b=zi*zi;if(a+b>4)break;double nz=a-b+cr;zi=2*zr*zi+ci;zr=nz;it++;}sum+=it;}}return sum;}
static int bench_mandel(uint64_t wu,int r){int w=(int)wu;(void)mandel(w>128?128:w,20);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=0;for(int x=0;x<r;x++){double s=now_s();c=mandel(w,50);t[x]=now_s()-s;}double m=median(t,r);uint64_t p=wu*wu;emit("mandelbrot",p,r,m,(double)p/m/1e6,c);free(t);return 0;}

struct Vec{uint64_t*p;size_t n,cap;};
static void vpush(struct Vec*v,uint64_t x){if(v->n==v->cap){size_t nc=v->cap?v->cap*2:8;v->p=realloc(v->p,nc*8);v->cap=nc;}v->p[v->n++]=x;}
static uint64_t va_once(size_t n){struct Vec v={0};for(size_t i=0;i<n;i++)vpush(&v,mix64(i));uint64_t h=0;for(size_t i=0;i<n;i++){v.p[i]^=i;h+=v.p[i];}while(v.n)h^=v.p[--v.n];free(v.p);return h;}
static int bench_va(uint64_t nu,int r){double*t=malloc((size_t)r*sizeof(*t));uint64_t c=va_once((size_t)nu/20+1);for(int x=0;x<r;x++){double s=now_s();c=va_once((size_t)nu);t[x]=now_s()-s;}double m=median(t,r);emit("dynamic_array",nu,r,m,(double)nu/m/1e6,c);free(t);return 0;}

static uint64_t ll_once(uint32_t*next,uint64_t*val,size_t n,int passes){for(size_t i=0;i<n;i++){next[i]=(uint32_t)(i+1<n?i+1:UINT32_MAX);val[i]=mix64(i);}const size_t B=64;for(size_t b=0;b<n;b+=B){size_t hi=(b+B<n?b+B:n)-1;for(size_t i=b;i<=hi;i++)next[i]=i==b?(uint32_t)(hi+1<n?hi+1:UINT32_MAX):(uint32_t)(i-1);}uint64_t h=0;for(int p=0;p<passes;p++){uint32_t cur=(uint32_t)(B<n?B-1:n-1);size_t seen=0;while(cur!=UINT32_MAX&&seen<n){val[cur]^=seen+p;h+=val[cur];cur=next[cur];seen++;}h^=seen;}return h;}
static int bench_ll(uint64_t nu,int r){const int p=16;size_t n=(size_t)nu;uint32_t*next=malloc(n*4);uint64_t*val=malloc(n*8);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=ll_once(next,val,n,1);for(int x=0;x<r;x++){double s=now_s();c=ll_once(next,val,n,p);t[x]=now_s()-s;}double m=median(t,r);emit("linked_list",nu*p,r,m,(double)n*p/m/1e6,c);free(t);free(val);free(next);return 0;}

static uint64_t qr_once(uint64_t*b,size_t cap,uint64_t ops){size_t h=0,t=0,cnt=0;uint64_t z=0;for(uint64_t i=0;i<ops;i++){if((i&3)!=3){if(cnt==cap){z^=b[h];h=(h+1)%cap;cnt--;}b[t]=mix64(i);t=(t+1)%cap;cnt++;}else if(cnt){uint64_t x=b[h];h=(h+1)%cap;cnt--;z+=x;}}while(cnt){z^=b[h];h=(h+1)%cap;cnt--;}return z;}
static int bench_qr(uint64_t ops,int r){size_t cap=(size_t)(ops/2+1024);uint64_t*b=malloc(cap*8);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=qr_once(b,cap,ops/20+1);for(int x=0;x<r;x++){double s=now_s();c=qr_once(b,cap,ops);t[x]=now_s()-s;}double m=median(t,r);emit("queue_ring",ops,r,m,(double)ops/m/1e6,c);free(t);free(b);return 0;}

static size_t np2(size_t x){size_t p=1;while(p<x)p<<=1;return p;}
static uint64_t ht_once(uint64_t*k,uint64_t*v,size_t cap,size_t n){memset(k,0,cap*8);uint64_t h=0;size_t mask=cap-1;for(size_t i=0;i<n;i++){uint64_t key=mix64(i)|1ULL,val=mix64(i+UINT64_C(0x55555555));size_t p=(size_t)mix64(key)&mask;while(k[p]&&k[p]!=key)p=(p+1)&mask;k[p]=key;v[p]=val;}for(size_t i=0;i<n;i++){uint64_t key=mix64(i)|1ULL;size_t p=(size_t)mix64(key)&mask;while(k[p]!=key)p=(p+1)&mask;v[p]^=i;h+=v[p];}return h;}
static int bench_ht(uint64_t nu,int r){size_t n=(size_t)nu,cap=np2(n*2);uint64_t*k=calloc(cap,8),*v=malloc(cap*8);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=ht_once(k,v,cap,n/20+1);for(int x=0;x<r;x++){double s=now_s();c=ht_once(k,v,cap,n);t[x]=now_s()-s;}double m=median(t,r);emit("hash_table",nu,r,m,(double)(n*2)/m/1e6,c);free(t);free(v);free(k);return 0;}

static void bhpush(uint64_t*h,size_t*sz,uint64_t x){size_t i=(*sz)++;while(i){size_t p=(i-1)/2;if(h[p]<=x)break;h[i]=h[p];i=p;}h[i]=x;}
static uint64_t bhpop(uint64_t*h,size_t*sz){uint64_t o=h[0],x=h[--*sz];size_t i=0;while(1){size_t l=i*2+1;if(l>=*sz)break;size_t r=l+1,c=r<*sz&&h[r]<h[l]?r:l;if(h[c]>=x)break;h[i]=h[c];i=c;}if(*sz)h[i]=x;return o;}
static uint64_t bh_once(uint64_t*h,size_t n){size_t sz=0;for(size_t i=0;i<n;i++)bhpush(h,&sz,mix64(i));uint64_t c=0;for(size_t i=0;i<n;i++)c^=bhpop(h,&sz)+i;return c;}
static int bench_bh(uint64_t nu,int r){size_t n=(size_t)nu;uint64_t*h=malloc(n*8);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=bh_once(h,n/20+1);for(int x=0;x<r;x++){double s=now_s();c=bh_once(h,n);t[x]=now_s()-s;}double m=median(t,r);emit("binary_heap",nu,r,m,(double)(n*2)/m/1e6,c);free(t);free(h);return 0;}

static uint64_t bst_once(uint64_t*k,int32_t*l,int32_t*rr,size_t n){int32_t root=-1;size_t used=0;for(size_t i=0;i<n;i++){uint64_t key=mix64(i);int32_t node=(int32_t)used++;k[node]=key;l[node]=rr[node]=-1;if(root<0){root=node;continue;}int32_t c=root;while(1){if(key<k[c]){if(l[c]<0){l[c]=node;break;}c=l[c];}else{if(rr[c]<0){rr[c]=node;break;}c=rr[c];}}}uint64_t h=0;for(size_t i=0;i<n;i+=3){uint64_t key=mix64(i);int32_t c=root;while(c>=0&&k[c]!=key)c=key<k[c]?l[c]:rr[c];h+=c>=0?(uint64_t)c+1:0;}return h;}
static int bench_bst(uint64_t nu,int r){size_t n=(size_t)nu;uint64_t*k=malloc(n*8);int32_t*l=malloc(n*4),*rr=malloc(n*4);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=bst_once(k,l,rr,n/20+1);for(int x=0;x<r;x++){double s=now_s();c=bst_once(k,l,rr,n);t[x]=now_s()-s;}double m=median(t,r);emit("bst",nu,r,m,(double)n/m/1e6,c);free(t);free(rr);free(l);free(k);return 0;}

static uint64_t trie_once(int32_t*ch,uint8_t*term,size_t mx,size_t words,int passes){for(size_t i=0;i<mx*16;i++)ch[i]=-1;memset(term,0,mx);size_t used=1;for(size_t i=0;i<words;i++){uint32_t w=(uint32_t)mix64(i);int32_t node=0;for(int sh=28;sh>=0;sh-=4){int c=(w>>sh)&15;int32_t*p=&ch[(size_t)node*16+c];if(*p<0)*p=(int32_t)used++;node=*p;}term[node]=1;}uint64_t h=used;for(int p=0;p<passes;p++)for(size_t i=0;i<words;i+=2){uint32_t w=(uint32_t)mix64(i);int32_t node=0;for(int sh=28;sh>=0&&node>=0;sh-=4)node=ch[(size_t)node*16+((w>>sh)&15)];if(node>=0&&term[node])h+=(uint64_t)node+1+p;}return h;}
static int bench_trie(uint64_t wu,int r){const int p=32;size_t w=(size_t)wu,mx=1+w*8;int32_t*ch=malloc(mx*16*4);uint8_t*term=malloc(mx);double*t=malloc((size_t)r*sizeof(*t));uint64_t c=trie_once(ch,term,mx,w/20+1,1);for(int x=0;x<r;x++){double s=now_s();c=trie_once(ch,term,mx,w,p);t[x]=now_s()-s;}double m=median(t,r);emit("trie",wu*p,r,m,(double)w*p/m/1e6,c);free(t);free(term);free(ch);return 0;}

static uint64_t dsize(const char*k){
if(!strcmp(k,"integer50"))return 200000000;if(!strcmp(k,"json_escape"))return 16000000;if(!strcmp(k,"merge_sort"))return 1000000;if(!strcmp(k,"binary_search"))return 1000000;if(!strcmp(k,"prefix_sum"))return 8000000;if(!strcmp(k,"matrix_mul"))return 320;if(!strcmp(k,"bfs"))return 200000;if(!strcmp(k,"dijkstra"))return 100000;if(!strcmp(k,"union_find"))return 1000000;if(!strcmp(k,"mandelbrot"))return 1600;if(!strcmp(k,"dynamic_array"))return 5000000;if(!strcmp(k,"linked_list"))return 4000000;if(!strcmp(k,"queue_ring"))return 10000000;if(!strcmp(k,"hash_table"))return 1000000;if(!strcmp(k,"binary_heap"))return 1000000;if(!strcmp(k,"bst"))return 300000;if(!strcmp(k,"trie"))return 100000;return 0;}
static int run(const char*k,uint64_t n,int r){
if(!strcmp(k,"integer50"))return bench_integer(n,r);if(!strcmp(k,"json_escape"))return bench_json(n,r);if(!strcmp(k,"merge_sort"))return bench_merge(n,r);if(!strcmp(k,"binary_search"))return bench_bs(n,r);if(!strcmp(k,"prefix_sum"))return bench_prefix(n,r);if(!strcmp(k,"matrix_mul"))return bench_mm(n,r);if(!strcmp(k,"bfs"))return bench_bfs(n,r);if(!strcmp(k,"dijkstra"))return bench_dij(n,r);if(!strcmp(k,"union_find"))return bench_uf(n,r);if(!strcmp(k,"mandelbrot"))return bench_mandel(n,r);if(!strcmp(k,"dynamic_array"))return bench_va(n,r);if(!strcmp(k,"linked_list"))return bench_ll(n,r);if(!strcmp(k,"queue_ring"))return bench_qr(n,r);if(!strcmp(k,"hash_table"))return bench_ht(n,r);if(!strcmp(k,"binary_heap"))return bench_bh(n,r);if(!strcmp(k,"bst"))return bench_bst(n,r);if(!strcmp(k,"trie"))return bench_trie(n,r);return 64;}
int main(int argc,char**argv){const char*k=argc>1?argv[1]:"integer50";uint64_t n=argc>2?strtoull(argv[2],0,10):dsize(k);int r=argc>3?atoi(argv[3]):7;if(!n||r<1)return 64;return run(k,n,r);}
